from collections import *

class Token:
    def __init__(self, value):
        self.value = value

def rpn_eval(tokens: List[Token]) -> float:
    def op(symbol: str, a: float, b: float) -> float:
        return {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b
        }[symbol](a, b)

    stack = []

    for token in tokens:
        if isinstance(token.value, float):
            stack.append(token.value)
        else:
            a = stack.pop()
            b = stack.pop()
            stack.append(
                op(token.value, a, b)
            )

    return stack[-1]
